//! The C entry points a scene library exports, generated by [`kinetic_scene!`].
//!
//! Only plain data crosses the library boundary: an ABI version number, a status code, and
//! a buffer of bytes in the [wire format](crate::wire). Nothing depends on Rust's unstable
//! ABI, so the editor and a scene may be built by different compiler runs.
//!
//! [`kinetic_scene!`]: crate::kinetic_scene

use std::panic::{catch_unwind, AssertUnwindSafe};

use crate::scene::Scene;
use crate::wire;

/// Version of the entry points' signatures. The host checks it before calling anything else.
pub const ABI_VERSION: u32 = 1;

/// The scene ran and the buffer holds an encoded timeline.
pub const STATUS_OK: u32 = 0;
/// The scene panicked; the buffer holds the panic message as UTF-8.
pub const STATUS_PANIC: u32 = 1;
/// The timeline could not be encoded; the buffer holds the reason as UTF-8.
pub const STATUS_ENCODE: u32 = 2;
/// The host passed a null output pointer.
pub const STATUS_NULL: u32 = 3;

/// Bytes handed from a scene library to its host.
///
/// The library allocates them, so only the library may free them: the host copies what it
/// needs and hands the value back to the library's `kinetic_scene_free`.
#[repr(C)]
#[derive(Debug)]
pub struct SceneBytes {
    pub ptr: *mut u8,
    pub len: usize,
    pub cap: usize,
}

impl SceneBytes {
    /// No bytes. What the host passes in before the call.
    pub const EMPTY: Self = Self { ptr: std::ptr::null_mut(), len: 0, cap: 0 };

    #[doc(hidden)]
    pub fn from_vec(bytes: Vec<u8>) -> Self {
        let mut bytes = std::mem::ManuallyDrop::new(bytes);
        Self { ptr: bytes.as_mut_ptr(), len: bytes.len(), cap: bytes.capacity() }
    }

    /// Takes the allocation back.
    ///
    /// # Safety
    ///
    /// `self` must have come from [`SceneBytes::from_vec`] in this same library, and must not
    /// be used again afterwards.
    #[doc(hidden)]
    pub unsafe fn into_vec(self) -> Vec<u8> {
        if self.ptr.is_null() {
            return Vec::new();
        }
        // SAFETY: the caller guarantees these are the parts of a Vec built by from_vec here.
        unsafe { Vec::from_raw_parts(self.ptr, self.len, self.cap) }
    }

    /// The bytes, borrowed.
    ///
    /// # Safety
    ///
    /// `ptr` must be valid for reads of `len` bytes for as long as the slice is used, which
    /// holds between a successful build call and the matching free call.
    pub unsafe fn as_slice(&self) -> &[u8] {
        if self.ptr.is_null() {
            return &[];
        }
        // SAFETY: guaranteed by the caller.
        unsafe { std::slice::from_raw_parts(self.ptr, self.len) }
    }
}

/// Runs `scene` on a fresh [`Scene`], encodes the result into `out` and returns a status.
/// Panics inside the scene are caught and reported rather than unwinding into the host.
#[doc(hidden)]
pub fn run_scene(scene: fn(&mut Scene), out: &mut SceneBytes) -> u32 {
    let built = catch_unwind(AssertUnwindSafe(|| {
        let mut s = Scene::new();
        scene(&mut s);
        s.build()
    }));
    let (status, bytes) = match built {
        Ok(timeline) => match wire::encode(&timeline) {
            Ok(bytes) => (STATUS_OK, bytes),
            Err(error) => (STATUS_ENCODE, error.to_string().into_bytes()),
        },
        Err(payload) => {
            let message = payload
                .downcast_ref::<&str>()
                .map(|s| s.to_string())
                .or_else(|| payload.downcast_ref::<String>().cloned())
                .unwrap_or_else(|| "the scene panicked".to_string());
            (STATUS_PANIC, message.into_bytes())
        }
    };
    *out = SceneBytes::from_vec(bytes);
    status
}

/// Turns a scene function into a library the editor can load and reload.
///
/// Put this at the root of a scene crate built as a `cdylib`:
///
/// ```ignore
/// fn scene(s: &mut kinetic_core::Scene) { /* ... */ }
/// kinetic_core::kinetic_scene!(scene);
/// ```
///
/// It exports three C functions: `kinetic_scene_abi_version`, `kinetic_scene_build` and
/// `kinetic_scene_free`.
#[macro_export]
macro_rules! kinetic_scene {
    ($scene:path) => {
        /// The scene library ABI version this crate was built with.
        #[no_mangle]
        pub extern "C" fn kinetic_scene_abi_version() -> u32 {
            $crate::abi::ABI_VERSION
        }

        /// Runs the scene and writes the encoded timeline, or an error message, to `out`.
        ///
        /// # Safety
        ///
        /// `out` must be null or point to writable memory for one `SceneBytes`.
        #[no_mangle]
        pub unsafe extern "C" fn kinetic_scene_build(out: *mut $crate::abi::SceneBytes) -> u32 {
            // SAFETY: the caller passes null or a valid, writable pointer.
            match unsafe { out.as_mut() } {
                Some(out) => $crate::abi::run_scene($scene, out),
                None => $crate::abi::STATUS_NULL,
            }
        }

        /// Releases bytes returned by `kinetic_scene_build`.
        ///
        /// # Safety
        ///
        /// `bytes` must be exactly what `kinetic_scene_build` wrote, passed back once.
        #[no_mangle]
        pub unsafe extern "C" fn kinetic_scene_free(bytes: $crate::abi::SceneBytes) {
            // SAFETY: the caller hands back bytes this library allocated, once.
            drop(unsafe { bytes.into_vec() });
        }
    };
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::node::Circle;

    fn good(s: &mut Scene) {
        let dot = s.add(Circle::new(10.0));
        s.play(dot.move_to((5.0, 0.0)), 1.0);
    }

    fn bad(_: &mut Scene) {
        panic!("scene went wrong at line 3");
    }

    #[test]
    fn good_scene_returns_an_encoded_timeline() {
        let mut out = SceneBytes::EMPTY;
        assert_eq!(run_scene(good, &mut out), STATUS_OK);
        // SAFETY: out was just filled by run_scene and is freed right after.
        let timeline = wire::decode(unsafe { out.as_slice() }).expect("decode");
        assert_eq!(timeline.duration, 1.0);
        drop(unsafe { out.into_vec() });
    }

    #[test]
    fn panicking_scene_reports_its_message() {
        let mut out = SceneBytes::EMPTY;
        assert_eq!(run_scene(bad, &mut out), STATUS_PANIC);
        // SAFETY: as above.
        let message = String::from_utf8(unsafe { out.into_vec() }).expect("utf-8");
        assert_eq!(message, "scene went wrong at line 3");
    }

    #[test]
    fn empty_bytes_are_safe_to_read_and_free() {
        // SAFETY: EMPTY has a null pointer, which both functions treat as no bytes.
        unsafe {
            assert!(SceneBytes::EMPTY.as_slice().is_empty());
            assert!(SceneBytes::EMPTY.into_vec().is_empty());
        }
    }
}
